const e="b15d84c82f7d",n="vertaler + keurder (claude-opus-5-5)",a="2026-10-20",s=[{personId:"B",after:[],nudge:"Commencez par Benoît. Il se trouvait juste à côté d'une table. Cherchez la table et regardez quelles cases juste à côté sont libres.",reasoning:"La table est en rangée 4, colonne 4. À sa gauche, en rangée 4, colonne 3, se trouve une étagère, et personne ne peut s'y trouver. Il ne reste donc qu'une seule case juste à côté de la table.",answer:"Benoît se trouve en rangée 3, colonne 4, juste au-dessus de la table. Sur l'autre case juste à côté de la table se trouve une étagère."},{personId:"A",after:["B"],nudge:"Regardez Amélie. Elle se trouvait dans la 2e colonne. Quelles cases de la colonne 2 sont encore possibles ?",reasoning:"En rangée 1, colonne 2 se trouve une armoire et en rangée 4, colonne 2 une étagère : personne ne peut s'y trouver. Chaque rangée contient exactement une personne, et la rangée 3 est déjà occupée par Benoît. Il ne reste qu'une case dans la colonne 2.",answer:"Amélie se trouve en rangée 2, colonne 2. La colonne 2 contient une armoire (rangée 1) et une étagère (rangée 4), et la rangée 3 est occupée par Benoît."},{personId:"C",after:["B","A"],nudge:"Regardez Céline. Elle se trouvait devant une fenêtre. Cherchez les fenêtres sur le plan.",reasoning:"Trois cases se trouvent devant une fenêtre : rangée 1, colonne 3 ; rangée 3, colonne 1 ; et rangée 4, colonne 4. En rangée 4, colonne 4 se trouve une table, et la rangée 3 est déjà occupée par Benoît. Quelle fenêtre reste-t-il ?",answer:"Céline se trouve en rangée 1, colonne 3, devant la fenêtre du haut. La fenêtre de la rangée 3 est exclue à cause de Benoît, et devant la fenêtre de la rangée 4 se trouve une table."},{personId:"V",after:["B","A","C"],nudge:"Virginie est la victime et n'a pas de carte. Regardez quelle rangée et quelle colonne sont encore vides.",reasoning:"Chaque rangée et chaque colonne contient exactement une personne. Benoît, Amélie et Céline se trouvent déjà dans les rangées 3, 2 et 1, et dans les colonnes 4, 2 et 3. Seules la rangée 4 et la colonne 1 sont encore vides.",answer:"Virginie se trouve en rangée 4, colonne 1. C'est la seule rangée et la seule colonne où il n'y a encore personne."}],l="Virginie se trouvait dans la cave à vin. Benoît est le seul suspect qui s'y trouvait (Amélie et Céline étaient dans le cabinet de travail), donc Benoît est le coupable.",o={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},r={source:e,model:n,date:a,steps:s,murderer:l,review:o},t="850dbab4bf0c",c="vertaler (claude-opus-5-5)",i="2026-10-20",u=[{personId:"C",after:[],nudge:"Commencez par Céline. Elle se trouvait dans la rangée du bas. Quelles cases de la rangée 4 sont libres ?",reasoning:"La rangée du bas est la rangée 4. Dans les colonnes 2, 3 et 4 de cette rangée se trouvent des tables, et personne ne peut s'y trouver. Il ne reste qu'une seule case.",answer:"Céline se trouve en rangée 4, colonne 1. Les autres cases de la rangée 4 sont couvertes par des tables."},{personId:"A",after:["C"],nudge:"Regardez Adrien. Il se trouvait près d'une fenêtre. Cherchez les fenêtres sur le plan.",reasoning:"Il y a des fenêtres près de trois cases : rangée 1, colonne 1 ou 3 ; et rangée 4, colonne 1. Chaque colonne contient exactement une personne, et la colonne 1 est déjà occupée par Céline. Quelle fenêtre reste-t-il ?",answer:"Adrien se trouve en rangée 1, colonne 3, près de la fenêtre en haut. Les autres fenêtres sont dans la colonne 1, et celle-ci est occupée par Céline."},{personId:"B",after:["C","A"],nudge:"Regardez Béatrice. Elle était dans la 2e colonne. Quelles cases de la colonne 2 sont encore possibles ?",reasoning:"La rangée 1 est occupée par Adrien et la rangée 4 par Céline. En rangée 2, colonne 2 se trouve une armoire, et personne ne peut s'y trouver. Il ne reste qu'une case dans la colonne 2.",answer:"Béatrice se trouve en rangée 3, colonne 2. Les rangées 1 et 4 sont occupées, et dans la rangée 2, la colonne 2 est prise par une armoire."},{personId:"V",after:["C","A","B"],nudge:"Vianney est la victime et n'a pas de carte. Regardez quelle rangée et quelle colonne sont encore vides.",reasoning:"Chaque rangée et chaque colonne contient exactement une personne. Céline, Adrien et Béatrice se trouvent déjà dans les rangées 4, 1 et 3, et dans les colonnes 1, 3 et 2. Seules la rangée 2 et la colonne 4 sont encore vides.",answer:"Vianney se trouve en rangée 2, colonne 4. C'est la seule rangée et la seule colonne où il n'y a encore personne."}],d="Vianney se trouvait dans le cabinet de travail. Adrien est le seul suspect qui s'y trouvait (Béatrice et Céline étaient dans la cave à vin), donc Adrien est le coupable.",g={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},p={source:t,model:c,date:i,steps:u,murderer:d,review:g},m="0e590a513929",v="vertaler + keurder (claude-opus-5-5)",h="2026-10-20",b=[{personId:"C",after:[],nudge:"Commencez par Cédric. Sa carte dit qu'il se trouvait sur une chaise. Cherchez la chaise sur le plan.",reasoning:"Cédric se trouvait sur une chaise. Il n'y a qu'une seule chaise, dans le cabinet de travail. C'est donc là que se trouve Cédric.",answer:"Cédric se trouve en rangée 4, colonne 1. C'est là qu'est la seule chaise, et sa carte dit qu'il se trouvait sur une chaise."},{personId:"A",after:["C"],nudge:"Regardez Anaïs. Elle se trouvait dans la rangée du haut. Quelles cases de la rangée 1 sont encore possibles ?",reasoning:"En rangée 1, colonne 2 se trouve un piano et en rangée 1, colonne 3 une plante : personne ne peut s'y trouver. Chaque colonne contient exactement une personne, et la colonne 1 est déjà occupée par Cédric. Il ne reste qu'une case dans la rangée 1.",answer:"Anaïs se trouve en rangée 1, colonne 4. La rangée 1 contient un piano (colonne 2) et une plante (colonne 3), et la colonne 1 est occupée par Cédric."},{personId:"B",after:["C","A"],nudge:"Regardez Bérénice. Elle se trouvait dans la 2e colonne. Quelles cases de la colonne 2 sont encore possibles ?",reasoning:"Dans les rangées 1 et 2 de la colonne 2 se trouve un piano, et personne ne peut s'y trouver. La rangée 4 est déjà occupée par Cédric. Il ne reste qu'une case dans la colonne 2.",answer:"Bérénice se trouve en rangée 3, colonne 2. Le haut de la colonne 2 est pris par un piano, et la rangée 4 est occupée par Cédric."},{personId:"V",after:["C","A","B"],nudge:"Virgile est la victime et n'a pas de carte. Regardez quelle rangée et quelle colonne sont encore vides.",reasoning:"Chaque rangée et chaque colonne contient exactement une personne. Cédric, Anaïs et Bérénice se trouvent déjà dans les rangées 4, 1 et 3, et dans les colonnes 1, 4 et 2. Seules la rangée 2 et la colonne 3 sont encore vides.",answer:"Virgile se trouve en rangée 2, colonne 3. C'est la seule rangée et la seule colonne où il n'y a encore personne."}],C="Virgile se trouvait dans le boudoir. Anaïs est la seule suspecte qui s'y trouvait (Bérénice et Cédric étaient dans le cabinet de travail), donc Anaïs est la coupable.",q={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},A={source:m,model:v,date:h,steps:b,murderer:C,review:q},D="f5f4c3de566b",B="vertaler + keurder (claude-opus-5-5)",f="2026-10-20",y=[{personId:"D",after:[],nudge:"Commencez par David. Sa carte mentionne un objet. Combien de ces objets y a-t-il sur la grille ?",reasoning:"David se trouvait sur une chaise. Regardez le plan : il n'y a qu'une seule chaise, dans le cabinet de travail. Sur quelle case se trouve cette chaise ?",answer:"David se trouve en rangée 5, colonne 2. C'est là qu'est la seule chaise de la maison, et sa carte dit qu'il se trouvait sur une chaise."},{personId:"C",after:["D"],nudge:"Regardez Clément et les deux armoires. Quelles cases sont à côté d'une armoire, et lesquelles sont exclues par les cartes d'Alice et de Bastien ?",reasoning:"Clément se trouvait à côté d'une armoire, dans la même pièce. À côté de l'armoire de la chambre, il y a les cases rangée 1, colonne 4 ; rangée 2, colonne 5 ; et rangée 3, colonne 4. À côté de l'armoire de la cave à vin, il y a les cases rangée 4, colonne 5 ; et rangée 5, colonne 4. La colonne 5 revient à Alice (colonne de droite), la rangée 3 revient à Bastien et la rangée 5 est occupée par David. Quelle case reste-t-il ?",answer:"Clément se trouve en rangée 1, colonne 4. Les autres cases à côté d'une armoire sont exclues : la colonne 5 revient à Alice, la rangée 3 à Bastien et la rangée 5 est occupée par David."},{personId:"B",after:["D","C"],nudge:"Bastien était dans la 3e rangée. Parcourez les cases de cette rangée : lesquelles sont bloquées ou exclues à cause d'une colonne ?",reasoning:"Bastien était dans la 3e rangée. En rangée 3, colonne 3, il y a le piano : personne ne peut s'y trouver. La colonne 2 est occupée par David et la colonne 4 par Clément. La colonne 5 revient à Alice, car elle se trouvait dans la colonne de droite. Quelle case de la rangée 3 reste-t-il ?",answer:"Bastien se trouve en rangée 3, colonne 1. Dans la colonne 3, il y a le piano, les colonnes 2 et 4 sont occupées par David et Clément, et la colonne 5 revient à Alice."},{personId:"V",after:["D","C","B"],nudge:"Passons à la victime, Virgile. Quelles rangées et quelles colonnes sont encore libres, et quelle colonne revient déjà à Alice ?",reasoning:"Les rangées 1, 3 et 5 sont occupées, tout comme les colonnes 1, 2 et 4. Il reste les rangées 2 et 4 et les colonnes 3 et 5. La colonne 5 revient à Alice, donc Virgile doit être dans la colonne 3. En rangée 2, colonne 3, il y a le piano. Où Virgile peut-il encore se trouver ?",answer:"Virgile se trouve en rangée 4, colonne 3. La colonne 5 revient à Alice, donc il doit être dans la colonne 3, et en rangée 2, colonne 3, il y a le piano."},{personId:"A",after:["D","C","B","V"],nudge:"Alice est la dernière qui n'est pas encore sur la grille. Que dit sa carte, et quelle rangée est encore libre ?",reasoning:"Alice se trouvait dans la colonne de droite, donc dans la colonne 5. Les rangées 1, 3, 4 et 5 sont déjà occupées. Quelle case de la colonne 5 reste-t-il ?",answer:"Alice se trouve en rangée 2, colonne 5. Sa carte dit la colonne de droite, et les rangées 1, 3, 4 et 5 sont déjà occupées."}],L="Virgile gît dans le cabinet de travail, et David est le seul suspect qui se trouvait aussi dans le cabinet de travail. David est donc le coupable.",I={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},w={source:D,model:B,date:f,steps:y,murderer:L,review:I},V="144a6a6f16d9",z="vertaler + keurder (claude-opus-5-5)",Q="2026-10-20",F=[{personId:"B",after:[],nudge:"Commencez par Bernard, dans la rangée du haut. Quelles cases y sont bloquées, et que dit la carte d'Adrien sur la cave à vin ?",reasoning:"Bernard était dans la rangée du haut, la rangée 1. En rangée 1, colonne 1, il y a une armoire : personne ne peut s'y trouver. Les colonnes 3, 4 et 5 de la rangée 1 font partie de la cave à vin, et Adrien était la seule personne dans la cave à vin. Bernard ne peut donc pas s'y trouver. Quelle case de la rangée 1 reste-t-il ?",answer:"Bernard se trouve en rangée 1, colonne 2. Dans la colonne 1, il y a une armoire, et les colonnes 3 à 5 font partie de la cave à vin, où il n'y avait qu'Adrien."},{personId:"D",after:["B"],nudge:"Regardez Delphine et les chaises. Quelles cases sont juste à côté d'une chaise dans la même pièce, en dehors de la cave à vin ?",reasoning:"Delphine se trouvait juste à côté d'une chaise, dans la même pièce. Deux chaises sont dans la cave à vin, mais il n'y avait qu'Adrien là-bas. Les deux autres sont dans le jardin d'hiver, en rangée 4, colonne 2 ; et en rangée 5, colonne 1. Juste à côté, il y a les cases rangée 3, colonne 2 ; rangée 5, colonne 2 ; et rangée 4, colonne 1. La colonne 2 est occupée par Bernard. Quelle case reste-t-il ?",answer:"Delphine se trouve en rangée 4, colonne 1, juste à côté des chaises du jardin d'hiver. La cave à vin revient à Adrien, et les cases rangée 3, colonne 2 et rangée 5, colonne 2 sont exclues, car Bernard occupe la colonne 2."},{personId:"C",after:["B","D"],nudge:"Céline se trouvait sur un lit. Combien de cases le lit occupe-t-il, et quelle rangée est déjà occupée ?",reasoning:"Il y a un seul lit, dans la bibliothèque : il occupe les rangées 3 et 4 de la colonne 5. La rangée 4 est occupée par Delphine. Sur quelle case du lit Céline peut-elle encore se trouver ?",answer:"Céline se trouve en rangée 3, colonne 5. Le lit occupe les rangées 3 et 4 de la colonne 5, et la rangée 4 est occupée par Delphine."},{personId:"V",after:["B","D","C"],nudge:"Passons à la victime, Valérie. Quelles rangées sont encore libres, et dans laquelle Adrien doit-il aller ?",reasoning:"Les rangées 1, 3 et 4 sont occupées ; il reste donc les rangées 2 et 5. Adrien était dans la cave à vin, qui n'occupe que les rangées 1 et 2 ; la rangée 1 revient à Bernard, donc Adrien va dans la rangée 2. Valérie doit alors être dans la rangée 5. Les colonnes 1, 2 et 5 sont occupées, et en rangée 5, colonne 3, il y a la table. Où Valérie peut-elle encore se trouver ?",answer:"Valérie se trouve en rangée 5, colonne 4. La rangée 2 revient à Adrien (cave à vin), les colonnes 1, 2 et 5 sont occupées, et en rangée 5, colonne 3, il y a la table."},{personId:"A",after:["B","D","C","V"],nudge:"Adrien est le dernier qui n'est pas encore sur la grille. Que dit sa carte, et quelle rangée et quelle colonne sont encore libres ?",reasoning:"Adrien était dans la cave à vin, donc en rangée 1 ou 2. La rangée 1 est occupée par Bernard. La colonne 4 est occupée par Valérie et la colonne 5 par Céline. Quelle case de la cave à vin reste-t-il ?",answer:"Adrien se trouve en rangée 2, colonne 3, dans la cave à vin. La rangée 1 est occupée par Bernard, la colonne 4 par Valérie et la colonne 5 par Céline."}],x="Valérie gît dans la bibliothèque, et Céline est la seule suspecte qui se trouvait aussi dans la bibliothèque. Céline est donc la coupable.",$={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},E={source:V,model:z,date:Q,steps:F,murderer:x,review:$},_="dfa59a49f03b",j="vertaler + keurder (claude-opus-5-5)",G="2026-10-20",R=[{personId:"A",after:[],nudge:"Commencez par Anaïs. Cherchez l'étagère sur le plan et regardez quelles cases à côté sont libres.",reasoning:"Anaïs se trouvait à côté d'une étagère. Il n'y a qu'une seule étagère : en rangée 5, colonne 3, dans le salon. En rangée 4, colonne 3, il y a une plante, et la case rangée 5, colonne 2 est derrière un mur, dans le hall (et il y a aussi une plante). Quelle case à côté de l'étagère reste-t-il ?",answer:"Anaïs se trouve en rangée 5, colonne 4, à côté de l'étagère. En rangée 4, colonne 3, il y a une plante, et la case rangée 5, colonne 2 est derrière un mur, dans le hall."},{personId:"C",after:["A"],nudge:"Passons à Clément, dans la 4e rangée. Comparez sa carte avec celle de Benoît, et regardez aussi Anaïs.",reasoning:"Clément était dans la 4e rangée. Les colonnes 1 et 2 de la rangée 4 font partie du hall, et Benoît était seul dans le hall : Clément ne peut donc pas s'y trouver. En rangée 4, colonne 3, il y a une plante, et la colonne 4 est occupée par Anaïs. Quelle case de la rangée 4 reste-t-il ?",answer:"Clément se trouve en rangée 4, colonne 5. Les colonnes 1 et 2 de la rangée 4 sont dans le hall, où Benoît était seul ; dans la colonne 3, il y a une plante ; et la colonne 4 est occupée par Anaïs."},{personId:"D",after:["A","C"],nudge:"Regardez Delphine et la colonne 2. Quelles cases sont exclues par la carte de Benoît ?",reasoning:"Delphine était dans la 2e colonne. Les rangées 3, 4 et 5 de la colonne 2 font partie du hall, où Benoît était seul ; Delphine ne peut pas s'y trouver. En rangée 1, colonne 2, il y a une armoire : personne ne peut s'y trouver. Quelle case de la colonne 2 reste-t-il, alors ?",answer:"Delphine se trouve en rangée 2, colonne 2. Les rangées 3 à 5 de la colonne 2 sont dans le hall, où Benoît était seul, et en rangée 1, colonne 2, il y a une armoire."},{personId:"B",after:["A","C","D"],nudge:"Benoît était dans le hall. Quelles rangées et quelles colonnes du hall sont encore libres ?",reasoning:"Le hall occupe les rangées 3, 4 et 5 des colonnes 1 et 2. La rangée 4 est occupée par Clément, la rangée 5 par Anaïs et la colonne 2 par Delphine. Quelle case du hall reste-t-il pour Benoît ?",answer:"Benoît se trouve en rangée 3, colonne 1. Dans le hall, la rangée 4 (Clément), la rangée 5 (Anaïs) et la colonne 2 (Delphine) sont déjà occupées."},{personId:"V",after:["A","C","D","B"],nudge:"Valentin est le dernier qui n'est pas encore sur la grille. Quelle rangée et quelle colonne sont encore libres ?",reasoning:"Tous les suspects sont déjà placés. La rangée 1 est la seule rangée libre et la colonne 3 la seule colonne libre. Où se croisent-elles ?",answer:"Valentin se trouve en rangée 1, colonne 3. La rangée 1 et la colonne 3 sont la seule rangée et la seule colonne où il n'y a encore personne."}],k="Valentin gît dans le couloir. Delphine est la seule suspecte dans le couloir ; Delphine est donc la coupable.",S={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},O={source:_,model:j,date:G,steps:R,murderer:k,review:S},P="74a91d976380",T="vertaler + keurder (claude-opus-5-5)",U="2026-10-20",J=[{personId:"C",after:[],nudge:"Commencez par Céline. Combinez sa carte avec celle de Didier : quelle femme peut se trouver dans sa pièce ? Regardez ensuite les pièces de la moitié supérieure.",reasoning:"Céline est la seule femme ; d'après la carte de Didier, Céline est donc dans la même pièce que Didier. Céline était dans la moitié supérieure, mais pas dans la rangée 1 : cette rangée est pour Antoine (sa carte : rangée du haut). Dans la cave à vin, il ne reste alors que la rangée 2, et dans le salon aussi, car la rangée 3 y est une table. Céline et Didier ne peuvent pas tenir tous les deux dans une seule rangée. Dans la chambre, Benoît, Céline et Didier devraient se partager les rangées 2 et 3, et cela ne fait que deux rangées. Quelle pièce reste-t-il alors, et quelle case libre a-t-elle dans la moitié supérieure ?",answer:"Céline se trouve en rangée 3, colonne 2. Céline et Didier ne tiennent ensemble que dans le boudoir, et la seule case libre du boudoir dans la moitié supérieure est celle du tapis."},{personId:"A",after:["C"],nudge:"Regardez Antoine. Sa carte ne laisse plus que deux cases dans la rangée du haut. De quelle colonne Didier a-t-il besoin dans le boudoir ?",reasoning:"D'après sa carte, Antoine se trouvait dans la rangée 1 et dans la moitié gauche. La case de la colonne 2 est une table, donc seules les colonnes 1 et 3 restent possibles. Didier doit être avec Céline dans le boudoir, et le boudoir n'a que les colonnes 1 et 2. La colonne 2 est déjà à Céline, donc Didier a besoin de la colonne 1. Quelle case reste-t-il alors pour Antoine ?",answer:"Antoine se trouve en rangée 1, colonne 3. La colonne 1 est nécessaire pour Didier dans le boudoir, et dans la rangée 1, la colonne 2 est une table."},{personId:"E",after:["C","A"],nudge:`Regardez Étienne et Benoît. La chambre n'a que deux colonnes. Que signifie alors "quelque part à droite de Benoît" pour Étienne, et dans quelle rangée Benoît doit-il se trouver ?`,reasoning:"Benoît se trouvait dans la chambre, donc dans la colonne 5 ou 6. Étienne se trouvait quelque part à droite de lui ; Benoît est donc dans la colonne 5 et Étienne dans la colonne 6. La rangée 1 est à Antoine et la rangée 3 à Céline, donc il ne reste que la rangée 2 pour Benoît. Dans la colonne 6, les rangées 1, 2 et 3 sont alors exclues pour Étienne, et dans les rangées 4 et 5 il y a une table. Où Étienne peut-il encore se trouver ?",answer:"Étienne se trouve en rangée 6, colonne 6. Il doit être dans la colonne 6 ; la rangée 1 est pour Antoine, la rangée 2 pour Benoît, la rangée 3 pour Céline, et dans les rangées 4 et 5 il y a une table."},{personId:"B",after:["C","A","E"],nudge:"Benoît se trouvait dans la chambre. Barrez-y les rangées et les colonnes déjà occupées.",reasoning:"La chambre couvre les rangées 1 à 3 dans les colonnes 5 et 6. La rangée 1 est à Antoine, la rangée 3 à Céline et la colonne 6 à Étienne. Quelle case reste-t-il dans la chambre ?",answer:"Benoît se trouve en rangée 2, colonne 5. Dans la chambre, la rangée 1, la rangée 3 et la colonne 6 sont déjà occupées."},{personId:"V",after:["C","A","E","B"],nudge:"Maintenant Virgile. Regardez quelles rangées et quelles colonnes sont encore libres, et de quelle colonne Didier a déjà besoin.",reasoning:"Les rangées 4 et 5 et les colonnes 1 et 4 sont encore libres. Didier doit être avec Céline dans le boudoir, dans la colonne 1 (la colonne 2 est à Céline). Virgile doit donc être dans la colonne 4. Dans cette colonne, la rangée 5 est occupée par l'étagère. Quelle case reste-t-il ?",answer:"Virgile se trouve en rangée 4, colonne 4. La colonne 1 est pour Didier, et dans la colonne 4, la rangée 5 est une étagère."},{personId:"D",after:["C","A","E","B","V"],nudge:"Didier est le dernier. Quelle rangée et quelle colonne sont encore entièrement libres ?",reasoning:"Il ne reste qu'une rangée libre et une colonne libre. Où se croisent-elles ? Regardez si cette case correspond à la carte de Didier : il doit être dans la même pièce que Céline.",answer:"Didier se trouve en rangée 5, colonne 1. C'est la seule rangée et la seule colonne libres, et cette case est dans le boudoir, avec Céline."}],M="Virgile gît dans la cuisine et Étienne est le seul suspect qui s'y trouve. Étienne est donc le coupable.",N={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},H={source:P,model:T,date:U,steps:J,murderer:M,review:N},K="a6ef3e81331a",W="vertaler + keurder (claude-opus-5-5)",X="2026-10-20",Y=[{personId:"E",after:[],nudge:"Commencez par Étienne : il se trouvait près d'une fenêtre. Quelles fenêtres sont exclues par les cartes d'Anaïs et de Charles ? Regardez ensuite Bernard.",reasoning:"La rangée 1 est pour Anaïs et la colonne 6 pour Charles ; de toutes les fenêtres, il ne reste donc que celles près de la case rangée 6, colonne 1 et de la case rangée 6, colonne 3 : Étienne était dans la rangée 6, dans le hall. Bernard se trouvait dans un coin de la pièce, avec un autre homme : Charles ou Étienne. Les coins du boudoir, où était Charles, sont tous dans la rangée 1, la rangée 6 ou la colonne 6, et celles-ci sont réservées à Anaïs, Étienne et Charles. Bernard était donc avec Étienne dans le hall, dans un coin hors de la rangée 6 et hors de la colonne 4 (qui est pour Denise) : rangée 5, colonne 1. Quelle fenêtre reste-t-il pour Étienne, maintenant que la colonne 1 est pour Bernard ?",answer:"Étienne se trouve en rangée 6, colonne 3. La rangée 1 est pour Anaïs, la colonne 6 pour Charles et la colonne 1 pour Bernard ; il ne reste donc que la fenêtre près de la case rangée 6, colonne 3."},{personId:"B",after:["E"],nudge:"Bernard se trouvait dans un coin de la pièce, et il y avait aussi un homme dans sa pièce. Quel homme cela peut-il être : Charles ou Étienne ?",reasoning:"L'autre homme est Charles ou Étienne. Charles était dans la colonne 6, dans le boudoir ; les coins du boudoir sont dans la rangée 1 (pour Anaïs), la rangée 6 (occupée par Étienne) ou la colonne 6 (pour Charles). Bernard était donc avec Étienne dans le hall. Le hall a quatre coins : rangée 5, colonne 1 ; rangée 5, colonne 4 ; rangée 6, colonne 1 ; et rangée 6, colonne 4. La rangée 6 est occupée et la colonne 4 est pour Denise : quel coin reste-t-il ?",answer:"Bernard se trouve en rangée 5, colonne 1. Il devait être avec Étienne dans le hall, et parmi les coins de cette pièce, la rangée 6 est exclue (Étienne), tout comme la colonne 4 (Denise)."},{personId:"C",after:["E","B"],nudge:"Charles était dans la colonne 6 et quelque part au-dessus de Denise. Cherchez d'abord à quelle hauteur Denise peut se trouver dans la colonne 4.",reasoning:"Denise se trouvait dans la colonne 4. La rangée 1 est pour Anaïs, et les rangées 5 et 6 sont occupées ; il lui reste donc la rangée 2, 3 ou 4. En rangée 4, colonne 4, elle serait à côté de l'étagère en rangée 4, colonne 3, et c'est interdit. Denise est donc dans la rangée 2 ou 3. Dans la colonne 6, Charles a encore les rangées 2, 3 et 4 libres, mais il doit être quelque part au-dessus de Denise. Quelle rangée convient encore ?",answer:"Charles se trouve en rangée 2, colonne 6. Denise ne peut pas être plus bas que la rangée 3 (la rangée 4 est à côté de l'étagère), la rangée 1 est pour Anaïs et les rangées 5 et 6 sont occupées."},{personId:"D",after:["E","B","C"],nudge:"Denise se trouvait dans la 4e colonne. Quelles rangées sont encore libres, et où est l'étagère ?",reasoning:"Dans la colonne 4, la rangée 1 est pour Anaïs, et les rangées 2, 5 et 6 sont occupées par Charles, Bernard et Étienne. Il reste deux cases : rangée 3, colonne 4 ; et rangée 4, colonne 4. Denise ne se trouvait pas à côté d'une étagère, et il y en a une en rangée 4, colonne 3. Quelle case reste-t-il ?",answer:"Denise se trouve en rangée 3, colonne 4. La rangée 1 est pour Anaïs, les rangées 2, 5 et 6 sont occupées, et la case rangée 4, colonne 4 est à côté de l'étagère en rangée 4, colonne 3."},{personId:"V",after:["E","B","C","D"],nudge:"Les rangées 1 et 4 et les colonnes 2 et 5 sont encore libres. Quelle rangée revient à Anaïs ?",reasoning:"La rangée 1 est pour Anaïs, donc Véronique doit être dans la rangée 4. Les colonnes 2 et 5 y sont encore libres. En rangée 4, colonne 2, il y a une étagère, et personne ne peut s'y trouver. Quelle case reste-t-il ?",answer:"Véronique se trouve en rangée 4, colonne 5. La rangée 1 est pour Anaïs, et en rangée 4, colonne 2, il y a une étagère."},{personId:"A",after:["E","B","C","D","V"],nudge:"Plus qu'une personne. Que dit la carte d'Anaïs ?",reasoning:"Anaïs était dans la rangée du haut, la rangée 1. Toutes les colonnes sauf la colonne 2 sont déjà occupées. Quelle case est-ce ?",answer:"Anaïs se trouve en rangée 1, colonne 2. Elle était dans la rangée du haut, et la colonne 2 est la seule colonne libre."}],Z="Charles est le coupable : il est le seul suspect dans le boudoir, où Véronique a été retrouvée.",ee={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ne={source:K,model:W,date:X,steps:Y,murderer:Z,review:ee},ae="eee2a5a776d9",se="vertaler + keurder (claude-opus-5-5)",le="2026-10-20",oe=[{personId:"B",after:[],nudge:"Commencez par Benoît : la colonne de droite et un coin de la pièce. Regardez ensuite Émile, qui était dans une rangée plus basse que celle de Benoît.",reasoning:"La colonne de droite appartient entièrement au jardin d'hiver. Dans la colonne 6, les coins du jardin d'hiver sont dans les rangées 1 et 6. Émile était dans une rangée plus basse que celle de Benoît. Si Benoît était dans la rangée 6, la rangée du bas, personne ne pourrait être dans une rangée plus basse que la sienne. Quel coin reste-t-il alors ?",answer:"Benoît se trouve en rangée 1, colonne 6. Dans la colonne 6, le jardin d'hiver a des coins dans les rangées 1 et 6, et avec Benoît dans la rangée 6, Émile ne pourrait pas être dans une rangée plus basse que la sienne."},{personId:"C",after:["B"],nudge:"Cédric se trouvait dans la 4e colonne. Regardez la rangée 6 : qui peut encore y être ? Pensez à Émile et à son lit.",reasoning:"Émile se trouvait sur un lit. Les lits sont dans les colonnes 3 et 4, mais la colonne 4 est pour Cédric ; Émile est donc dans la colonne 3, dans la rangée 3 ou 4. Dans la rangée 6, il y a des tables dans les colonnes 1 et 2 et une plante dans la colonne 5, et la colonne 6 est occupée. La colonne 3 est pour Émile, qui ne peut pas être dans la rangée 6. Qui peut alors encore occuper la case de la rangée 6 ?",answer:"Cédric se trouve en rangée 6, colonne 4. Dans la rangée 6, il ne reste que les colonnes 3 et 4 ; la colonne 3 est pour Émile, sur le lit de la rangée 3 ou 4, donc la rangée 6 est pour Cédric."},{personId:"E",after:["B","C"],nudge:"Émile était sur le lit de la colonne 3, dans la rangée 3 ou 4. Regardez la carte d'Arthur : dans quel coin peut-il être ?",reasoning:"Arthur se trouvait dans un coin de la pièce, et dans sa pièce, il y avait une autre personne portant des lunettes. Les colonnes 3, 4 et 6 et les rangées 1 et 6 sont exclues pour lui. Il reste alors le coin rangée 2, colonne 1 dans la bibliothèque, et les coins rangée 3, colonne 1 et rangée 3, colonne 2 dans la chambre d'amis. Dans la bibliothèque, personne d'autre ne peut plus être avec lui, car la rangée 1 est occupée et en rangée 2, colonne 2, il y a une étagère. Arthur est donc dans la rangée 3. Quelle rangée Émile reçoit-il alors ?",answer:"Émile se trouve en rangée 4, colonne 3. Il doit être sur le lit de la colonne 3 ; la rangée 3 est pour Arthur, qui ne peut avoir une autre personne portant des lunettes avec lui que dans un coin de la chambre d'amis, dans la rangée 3."},{personId:"V",after:["B","C","E"],nudge:"Arthur était dans la rangée 3 de la chambre d'amis, avec une autre personne portant des lunettes. Qui est-ce, et quelle rangée et quelle colonne reste-t-il pour Vanessa ?",reasoning:"Arthur était dans la chambre d'amis, dans la rangée 3, comme on l'a vu. Émile porte aussi des lunettes, mais il est dans le cabinet de travail. Diane était donc avec Arthur dans la chambre d'amis. Les rangées 2 et 5 sont encore libres ; la chambre d'amis couvre les rangées 3 à 6, donc Diane reçoit la rangée 5. Arthur et Diane prennent les colonnes 1 et 2. Quelle rangée et quelle colonne reste-t-il pour Vanessa ?",answer:"Vanessa se trouve en rangée 2, colonne 5. Diane doit être avec Arthur dans la chambre d'amis, dans la rangée 5, et tous les deux prennent les colonnes 1 et 2 ; il reste la rangée 2 et la colonne 5 pour Vanessa."},{personId:"D",after:["B","C","E","V"],nudge:"Diane était dans la chambre d'amis, dans la rangée 5. Que dit sa carte sur Arthur ?",reasoning:"Diane était avec Arthur dans la chambre d'amis, dans la rangée 5, comme on l'a vu. Elle et Arthur ont les colonnes 1 et 2. Diane se trouvait quelque part à gauche d'Arthur. Laquelle des deux colonnes est à gauche ?",answer:"Diane se trouve en rangée 5, colonne 1. Elle et Arthur prennent les colonnes 1 et 2, et Diane se trouvait quelque part à gauche d'Arthur."},{personId:"A",after:["B","C","E","V","D"],nudge:"Arthur est le dernier. Quelle rangée et quelle colonne sont encore libres ?",reasoning:"Toutes les rangées sauf la rangée 3 sont occupées, et toutes les colonnes sauf la colonne 2. Cette case est un coin de la chambre d'amis, et Diane, avec ses lunettes, est dans la même pièce, comme le demande la carte d'Arthur.",answer:"Arthur se trouve en rangée 3, colonne 2. C'est la seule case libre, un coin de la chambre d'amis, avec Diane."}],re="Vanessa gît dans le jardin d'hiver, et Benoît est le seul suspect qui s'y trouve. Benoît est donc le coupable.",te={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ce={source:ae,model:se,date:le,steps:oe,murderer:re,review:te},ie="fa9cb05db2c4",ue="vertaler + keurder (claude-opus-5-5)",de="2026-10-20",ge=[{personId:"F",after:[],nudge:"Commencez par Fabrice et Damien : Damien se trouvait exactement deux rangées en dessous de Fabrice. Quelles rangées restent possibles pour Damien si vous prenez aussi la carte d'Alice ?",reasoning:"En rangée 1, colonne 5 se trouve une étagère, donc Fabrice n'est pas dans la rangée 1 et Damien (deux rangées plus bas) est au moins dans la rangée 4. Alice se trouvait quelque part en dessous de Damien et quelque part au-dessus d'un homme, donc Alice n'est pas dans la rangée 7 et Damien n'est pas dans la rangée 6 ou 7. Dans la moitié gauche (colonnes 1 à 3), la rangée 4 ne contient que des étagères, donc Damien est dans la rangée 5. Fabrice était deux rangées plus haut : quelle case de la colonne 5 est-ce ?",answer:"Fabrice se trouve en rangée 3, colonne 5. Damien doit être dans la rangée 5 : à gauche, la rangée 4 ne contient que des étagères, et dans la rangée 6 ou 7, Alice ne pourrait pas être à la fois en dessous de lui et au-dessus d'un homme."},{personId:"C",after:["F"],nudge:"Cédric était dans la 3e colonne. Regardez quelles rangées sont déjà prises par d'autres : pensez à Damien, Alice et Émile.",reasoning:"Damien est dans la rangée 5, comme on l'a vu. Alice se trouvait quelque part en dessous de Damien et quelque part au-dessus d'un homme, donc Alice est dans la rangée 6. Émile se trouvait dans la cave à vin (rangées 6 et 7), donc Émile est dans la rangée 7. Dans la colonne 3, il y a une table en rangée 2, une étagère en rangée 4 et une armoire en rangée 6, et la rangée 3 est occupée par Fabrice. Quelle case reste-t-il pour Cédric ?",answer:"Cédric se trouve en rangée 1, colonne 3. La rangée 3 est à Fabrice, la rangée 5 à Damien, la rangée 6 à Alice et la rangée 7 à Émile ; dans la colonne 3, il y a une table en rangée 2, une étagère en rangée 4 et une armoire en rangée 6."},{personId:"A",after:["F","C"],nudge:"Alice est dans la rangée 6. Regardez Bérénice : elle était exactement une colonne à gauche d'Alice. Quelles colonnes sont déjà prises ?",reasoning:"Alice est dans la rangée 6, comme on l'a vu. Damien se trouvait dans la moitié gauche et la colonne 3 est occupée par Cédric ; comme Émile était dans une colonne plus à gauche que celle de Damien, la colonne 2 est pour Damien et la colonne 1 pour Émile. Dans la rangée 6, il y a des armoires dans les colonnes 3 et 5, donc il reste pour Alice les colonnes 4, 6 et 7 de la rangée 6. Bérénice était exactement une colonne à gauche d'Alice, mais la colonne 3 est occupée par Cédric et la colonne 5 par Fabrice. Quelle place reste-t-il alors à Alice ?",answer:"Alice se trouve en rangée 6, colonne 7. Les colonnes 1 et 2 sont pour Émile et Damien, il y a des armoires dans les colonnes 3 et 5, et en colonne 4 ou 6, Bérénice devrait être dans la colonne 3 (Cédric) ou 5 (Fabrice)."},{personId:"B",after:["F","C","A"],nudge:"Regardez la rangée 4. Quelles cases y sont encore libres, et qui peut encore s'y trouver ?",reasoning:"Bérénice était exactement une colonne à gauche d'Alice, donc la colonne 6 est pour Bérénice. Dans la rangée 4, il y a des étagères dans les colonnes 1 à 4, la colonne 5 est occupée par Fabrice et la colonne 7 par Alice. Il ne reste qu'une case dans la rangée 4, et chaque rangée contient exactement une personne. Qui doit donc s'y trouver ?",answer:"Bérénice se trouve en rangée 4, colonne 6. Dans la rangée 4, il y a des étagères dans les colonnes 1 à 4, et les colonnes 5 et 7 sont à Fabrice et à Alice ; la colonne 6 est pour Bérénice."},{personId:"E",after:["F","C","A","B"],nudge:"Émile se trouvait dans la cave à vin et dans une colonne plus à gauche que celle de Damien. Quelle rangée et quelle colonne lui restent ?",reasoning:"La cave à vin occupe les rangées 6 et 7, et la rangée 6 est occupée par Alice, donc Émile est dans la rangée 7. Damien se trouvait dans la moitié gauche et la colonne 3 est occupée par Cédric, donc Damien est dans la colonne 1 ou 2. Émile était dans une colonne plus à gauche que celle de Damien, donc Émile doit être dans la colonne 1. De quelle case s'agit-il ?",answer:"Émile se trouve en rangée 7, colonne 1. La rangée 6 est à Alice, et dans une colonne plus à gauche que celle de Damien (colonne 1 ou 2, car la colonne 3 est à Cédric), il ne reste pour Émile que la colonne 1."},{personId:"D",after:["F","C","A","B","E"],nudge:"Que dit la carte de Damien ? Comparez-la avec la place de Fabrice.",reasoning:"Damien se trouvait exactement deux rangées en dessous de Fabrice, donc dans la rangée 5. Il se trouvait dans la moitié gauche, où la colonne 1 est occupée par Émile et la colonne 3 par Cédric. Quelle case reste-t-il dans la rangée 5 ?",answer:"Damien se trouve en rangée 5, colonne 2. Il se trouvait exactement deux rangées en dessous de Fabrice, et dans la moitié gauche, les colonnes 1 (Émile) et 3 (Cédric) sont déjà occupées."},{personId:"V",after:["F","C","A","B","E","D"],nudge:"Tous les suspects sont placés. Quelle rangée et quelle colonne sont encore entièrement vides ?",reasoning:"Chaque rangée et chaque colonne contient exactement une personne. La rangée 2 et la colonne 4 sont la seule rangée et la seule colonne où il n'y a encore personne. Sur la case où elles se croisent se trouve un canapé, et on peut s'y trouver. Vincent doit donc être là.",answer:"Vincent se trouve en rangée 2, colonne 4. C'est la seule rangée et la seule colonne encore vides."}],pe="Vincent se trouvait dans le cabinet de travail. Le seul suspect qui s'y trouvait est Fabrice, donc Fabrice est le coupable.",me={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ve={source:ie,model:ue,date:de,steps:ge,murderer:pe,review:me},he="e42c954df5cd",be="vertaler + keurder (claude-opus-5-5)",Ce="2026-10-20",qe=[{personId:"A",after:[],nudge:"Fixez d'abord les rangées de Damien et de Gilles, puis regardez Béatrice et Céline. Quelles rangées restent pour Anaïs et Florian ?",reasoning:"Damien est dans la rangée 2 et Gilles dans la rangée 3, donc Béatrice (moitié supérieure) doit être dans la rangée 1 ou 4. Céline était dans une rangée plus haute que celle de Béatrice, donc Béatrice est dans la rangée 4 et Céline dans la rangée 1. Les rangées 1 à 4 sont ainsi pour Céline, Damien, Gilles et Béatrice, donc Anaïs et Florian doivent être dans les rangées 5 à 8. Là, juste à côté d'une table, Anaïs peut être en rangée 5, colonne 7 ; rangée 5, colonne 8 ; ou rangée 6, colonne 7 (la case en rangée 7, colonne 8 ne compte pas : un mur la sépare de la table). Florian se trouvait quelque part au-dessus d'Anaïs : dans quelle rangée Anaïs ne peut-elle donc pas être ?",answer:"Anaïs se trouve en rangée 6, colonne 7. Les rangées 1 à 4 sont pour Céline, Damien, Gilles et Béatrice ; juste à côté d'une table, elle peut être dans la rangée 5 ou 6, et dans la rangée 5, Florian ne pourrait pas être quelque part au-dessus d'elle."},{personId:"C",after:["A"],nudge:"Céline est dans la rangée 1, comme on l'a vu pour Anaïs. Cherchez d'abord dans quelle pièce est Béatrice, puis lisez la carte d'Étienne.",reasoning:"Béatrice est dans la rangée 4, et quelqu'un d'autre dans sa pièce était une femme. Dans le boudoir, c'est impossible (Céline est dans la rangée 1, Anaïs dans la cuisine), donc Béatrice est dans la cuisine, dans la colonne 4 ou plus à droite. Étienne était dans une colonne plus à droite que celle d'une femme : pas Céline, car il se trouvait quelque part à gauche d'elle, donc Béatrice ou Anaïs. Étienne est ainsi dans la colonne 5 ou plus à droite, et Céline encore plus à droite. En rangée 1, colonne 6 se trouve une étagère et la colonne 7 est occupée par Anaïs : quelle colonne reste-t-il ?",answer:"Céline se trouve en rangée 1, colonne 8. Étienne était dans une colonne plus à droite que celle de Béatrice (cuisine, colonne 4 ou plus) ou d'Anaïs, donc dans la colonne 5 ou plus, et Céline encore plus à droite ; en rangée 1, colonne 6 se trouve une étagère et la colonne 7 est occupée."},{personId:"G",after:["A","C"],nudge:"Gilles est dans la rangée 3, mais pas dans le jardin d'hiver. Quelles cases de la rangée 3 restent alors ?",reasoning:"Gilles se trouvait dans la 3e rangée et n'était pas dans le jardin d'hiver, donc il n'est pas dans la colonne 1, 2 ou 3. Dans la rangée 3, une table occupe les colonnes 5 et 6, et les colonnes 7 et 8 sont occupées par Anaïs et Céline. Quelle case est encore libre ?",answer:"Gilles se trouve en rangée 3, colonne 4. Les colonnes 1 à 3 forment le jardin d'hiver, dans la rangée 3, une table occupe les colonnes 5 et 6, et les colonnes 7 et 8 sont occupées."},{personId:"B",after:["A","C","G"],nudge:"Béatrice est dans la cuisine, dans la rangée 4. Regardez quelles colonnes sont encore libres, et pensez à Étienne.",reasoning:"Béatrice est dans la cuisine, dans la rangée 4, comme on l'a vu. Les colonnes 4 et 8 sont occupées par Gilles et Céline et en rangée 4, colonne 7 se trouve une table, donc Béatrice est dans la colonne 5 ou 6. Étienne était dans la colonne 5 ou plus à droite (voir Céline) et quelque part à gauche de Céline, qui est dans la colonne 8 ; la colonne 7 est occupée, donc Étienne est dans la colonne 5 ou 6. Si Béatrice était dans la colonne 6, Étienne devrait être dans la colonne 5, mais alors aucune femme ne serait dans une colonne plus à gauche que la sienne. Quelle colonne Béatrice prend-elle alors ?",answer:"Béatrice se trouve en rangée 4, colonne 5. Elle doit être dans la cuisine, dans la colonne 5 ou 6, et dans la colonne 6, Étienne serait dans la colonne 5, sans femme dans une colonne plus à gauche que la sienne."},{personId:"E",after:["A","C","G","B"],nudge:"Étienne devait être dans la colonne 5 ou 6. Béatrice est maintenant dans la colonne 5. Quelles rangées sont encore libres dans la colonne 6 ?",reasoning:"Étienne est dans la colonne 5 ou 6, comme on l'a vu, et la colonne 5 est occupée par Béatrice. Les rangées 1, 3, 4 et 6 sont déjà occupées par Céline, Gilles, Béatrice et Anaïs, et la rangée 2 est pour Damien. Florian devait être dans les rangées 5 à 8 et quelque part au-dessus d'Anaïs (rangée 6), donc la rangée 5 est pour Florian. En rangée 8, colonne 6 se trouve une armoire. Quelle case reste-t-il pour Étienne dans la colonne 6 ?",answer:"Étienne se trouve en rangée 7, colonne 6. Il doit être dans la colonne 6 ; les rangées 1, 3, 4 et 6 sont occupées, la rangée 2 est pour Damien, la rangée 5 pour Florian (au-dessus d'Anaïs) et en rangée 8, colonne 6 se trouve une armoire."},{personId:"F",after:["A","C","G","B","E"],nudge:"Florian est dans la rangée 5. Lisez la deuxième phrase de sa carte.",reasoning:"Florian est dans la rangée 5, comme on l'a vu. Les colonnes 4 à 8 sont occupées, donc les colonnes 1, 2 et 3 sont encore libres. Florian était exactement deux colonnes à droite d'un homme. Dans la colonne 1 ou 2, il n'existe pas de colonne deux colonnes plus à gauche. Quelle colonne reste-t-il ?",answer:"Florian se trouve en rangée 5, colonne 3. Les colonnes 4 à 8 sont occupées, et dans la colonne 1 ou 2, il ne pourrait pas être exactement deux colonnes à droite d'un homme."},{personId:"V",after:["A","C","G","B","E","F"],nudge:"Où gît Vianney ? Regardez quelles rangées et quelles colonnes sont encore libres, et pensez à la carte de Damien.",reasoning:"Les rangées 2 et 8 et les colonnes 1 et 2 sont encore libres. Damien se trouvait dans la 2e rangée, donc Vianney va dans la rangée 8. En rangée 8, colonne 1 se trouve une plante. Sur quelle case va alors Vianney ?",answer:"Vianney se trouve en rangée 8, colonne 2. La rangée 2 est pour Damien, et en rangée 8, colonne 1 se trouve une plante."},{personId:"D",after:["A","C","G","B","E","F","V"],nudge:"Que dit la carte de Damien ?",reasoning:"Damien se trouvait dans la 2e rangée. Quelle colonne y est encore libre ?",answer:"Damien se trouve en rangée 2, colonne 1. La rangée 2 est la sienne, et la colonne 1 est la seule colonne libre."}],Ae="Vianney gît dans le boudoir, et Florian est le seul suspect dans cette pièce : Damien est dans le jardin d'hiver, Céline et Gilles dans la chambre, Béatrice et Anaïs dans la cuisine et Étienne dans la chambre d'amis. Florian est donc le coupable.",De={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},Be={source:he,model:be,date:Ce,steps:qe,murderer:Ae,review:De},fe="fd37cde9aa3a",ye="vertaler + keurder (claude-opus-5-5)",Le="2026-10-20",Ie=[{personId:"B",after:[],nudge:"Regardez les colonnes 1 et 2 : dans quelles pièces sont-elles, et qui, d'après sa carte, ne peut pas du tout s'y trouver ?",reasoning:"Les colonnes 1 et 2 sont dans le boudoir et la chambre, et chacune de ces pièces a une chaise. François et David étaient dans une pièce sans chaise, donc pas là ; David était dans la même pièce que Clémence, donc Clémence non plus. Amélie se trouvait quelque part à droite de Clémence, et Élise exactement quatre colonnes à droite de Clémence, donc elles non plus. Les colonnes 1 et 2 sont donc pour Benoît et Valérie. Benoît se trouvait dans la 5e rangée et ne se trouvait pas à côté d'un canapé : en rangée 5, colonne 2, il serait à côté du canapé de la colonne 1 (rangées 4 et 5). Qui se trouve sur le canapé lui-même n'est pas à côté. Où est alors Benoît ?",answer:"Benoît se trouve en rangée 5, colonne 1. Les colonnes 1 et 2 ne sont que pour Benoît et Valérie (les deux pièces ont une chaise), et en rangée 5, colonne 2, Benoît serait à côté d'un canapé."},{personId:"V",after:["B"],nudge:"Regardez la rangée 7 : quelqu'un doit s'y trouver. Réfléchissez d'abord à la colonne où Clémence peut être.",reasoning:"Dans la rangée 7, une table occupe les colonnes 5, 6 et 7, et la colonne 1 est occupée. Élise se trouvait exactement quatre colonnes à droite de Clémence, donc Clémence est dans la colonne 1, 2 ou 3, et dans une pièce sans chaise (celle de David) : ce n'est possible que dans la cuisine, dans la colonne 3. David est aussi dans la cuisine, et comme la colonne 3 est pour Clémence, la colonne 4 est pour David. Les colonnes 3 et 4 de la rangée 7 sont donc exclues. La colonne 2 est pour Valérie, comme on l'a vu. Quelle case reste-t-il dans la rangée 7 ?",answer:"Valérie se trouve en rangée 7, colonne 2. Quelqu'un doit être dans la rangée 7 : la colonne 1 est occupée, une table occupe les colonnes 5 à 7, et les colonnes 3 et 4 sont pour Clémence et David dans la cuisine."},{personId:"E",after:["B","V"],nudge:"Clémence est dans la colonne 3. Où est alors Élise ? Elle était exactement quatre rangées au-dessus d'un homme : quel homme cela peut-il être ?",reasoning:"Clémence est dans la colonne 3, donc Élise est quatre colonnes plus loin, dans la colonne 7. Élise était exactement quatre rangées au-dessus d'un homme, donc elle est dans la rangée 1, 2 ou 3. Dans la rangée 7, il y a Valérie, une femme, donc la rangée 3 est exclue. Dans la rangée 6, il ne peut y avoir aucun homme : David est dans la cuisine, François était dans une pièce sans chaise, et la chambre a une chaise. La rangée 2 est donc exclue aussi. Quel homme est dans la rangée 5 ?",answer:"Élise se trouve en rangée 1, colonne 7. Elle doit être dans la colonne 7 (exactement quatre colonnes à droite de Clémence) et exactement quatre rangées au-dessus d'un homme : c'est Benoît, dans la rangée 5 ; la rangée 6 ne peut pas avoir d'homme et dans la rangée 7, il y a Valérie."},{personId:"A",after:["B","V","E"],nudge:"Regardez la colonne 6 : quelles cases y sont encore libres, et qui peut être dans cette pièce ?",reasoning:"Quelqu'un doit être dans la colonne 6. Un piano y occupe les rangées 2 et 3, il y a une armoire en rangée 4 et une table en rangée 7 ; les rangées 1 et 5 sont occupées. Il ne reste que la case en rangée 6, colonne 6, dans la chambre, où il y a une chaise. Clémence et David sont dans la cuisine, et François était dans une pièce sans chaise. Qui reste-t-il alors pour cette case ?",answer:"Amélie se trouve en rangée 6, colonne 6. C'est la seule case libre de la colonne 6 (piano, armoire et table bloquent le reste), et Clémence, David et François ne peuvent pas être dans la chambre, avec sa chaise."},{personId:"F",after:["B","V","E","A"],nudge:"Quelle colonne reste-t-il pour François ? Regardez ensuite la carte de Clémence : exactement trois rangées plus bas, il doit y avoir un homme.",reasoning:"Les colonnes 3 et 4 sont pour Clémence et David, comme on l'a vu, donc François va dans la colonne 5. Les rangées 1, 5 et 6 y sont occupées et en rangée 7 se trouve une table, donc il reste les rangées 2, 3 et 4. Clémence se trouvait exactement trois rangées au-dessus d'un homme ; la rangée 1 est occupée et dans la rangée 3, Amélie serait trois rangées plus bas, donc Clémence est dans la rangée 2. David est alors dans la cuisine, dans la rangée 3. Quelle rangée reste-t-il pour François ?",answer:"François se trouve en rangée 4, colonne 5. Il doit être dans la colonne 5 ; la rangée 2 est pour Clémence (dans la rangée 3, Amélie serait trois rangées plus bas qu'elle) et la rangée 3 pour David dans la cuisine."},{personId:"C",after:["B","V","E","A","F"],nudge:"Clémence est dans la colonne 3, dans la cuisine. Qui se trouve trois rangées plus bas que chaque rangée encore libre pour elle ?",reasoning:"Clémence est dans la cuisine, dans la colonne 3, donc dans la rangée 1, 2 ou 3. La rangée 1 est occupée. Clémence se trouvait exactement trois rangées au-dessus d'un homme. Trois rangées sous la rangée 3, il y a Amélie, une femme. Qui se trouve trois rangées sous la rangée 2 ?",answer:"Clémence se trouve en rangée 2, colonne 3. La rangée 1 est occupée et dans la rangée 3, Amélie, une femme, serait trois rangées plus bas ; trois rangées sous la rangée 2, il y a Benoît."},{personId:"D",after:["B","V","E","A","F","C"],nudge:"David est le dernier. Que dit sa carte, et quelle rangée et quelle colonne sont encore vides ?",reasoning:"David était dans la même pièce que Clémence, donc dans la cuisine. Toutes les autres personnes sont placées, donc il reçoit la seule rangée et la seule colonne encore libres. Cette case est-elle dans la cuisine ?",answer:"David se trouve en rangée 3, colonne 4 : c'est la seule rangée et la seule colonne libres, et cette case est dans la cuisine, avec Clémence."}],we="Valérie gît dans la chambre, et Amélie est la seule suspecte dans cette pièce. Amélie est donc la coupable.",Ve={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ze={source:fe,model:ye,date:Le,steps:Ie,murderer:we,review:Ve},Qe="c895d9aa52fd",Fe="vertaler + keurder (claude-opus-5-5)",xe="2026-10-20",$e=[{personId:"B",after:[],nudge:"Commencez par Béatrice : de quel homme peut-elle être exactement trois colonnes à droite ? Regardez ensuite qui peut remplir les rangées 1, 2 et 8.",reasoning:"Guillaume est en colonne 1 (exactement deux colonnes à gauche d'Antoine, en colonne 3). Béatrice se trouvait exactement trois colonnes à droite d'un homme : depuis Antoine, c'est la colonne 6 (celle de Clément), depuis Clément la colonne 9 (inexistante), donc depuis Guillaume : la colonne 4. Qui peut remplir les rangées 1, 2 ou 8 ? Pas Denise (rangée 4). Ni Antoine ni Fanny : Fanny était exactement une rangée en dessous d'Antoine, dans la moitié inférieure ; en rangée 4, colonne 3 se trouve une étagère et la rangée 7 y est hors de la maison, donc Antoine est en rangée 5 ou 6, Fanny en rangée 6 ou 7. Pas Clément : dans la colonne 6, les rangées 1 et 2 sont hors de la maison et la 8 a une plante. Pas Guillaume : en rangée 1, colonne 1 se trouve une armoire, la rangée 8 y est hors de la maison, et depuis la rangée 2, il faudrait un homme dans la rangée 4, celle de Denise. Ces rangées reviennent donc à Béatrice, Émilie et Virginie. Laquelle offre un coin à Béatrice dans la colonne 4 ?",answer:"Béatrice se trouve en rangée 1, colonne 4 : exactement trois colonnes à droite de Guillaume. Seules elle, Émilie et Virginie peuvent remplir les rangées 1, 2 et 8 ; la case en rangée 2, colonne 4 n'est pas un coin et celle en rangée 8, colonne 4 est hors de la maison."},{personId:"E",after:["B"],nudge:"Les rangées 1, 2 et 8 reviennent à Béatrice, Émilie et Virginie. Émilie peut-elle être dans la rangée 8, alors qu'elle se trouvait quelque part au-dessus d'un homme ?",reasoning:"Comme on l'a vu avec Béatrice, les rangées 1, 2 et 8 reviennent à Béatrice, Émilie et Virginie, et Béatrice se trouve dans la rangée 1. Émilie se trouvait quelque part au-dessus d'un homme, donc pas dans la rangée 8 : elle va dans la rangée 2. La colonne 1 revient à Guillaume, la colonne 3 à Antoine, la colonne 4 est occupée par Béatrice, et les colonnes 6 à 8 de la rangée 2 sont hors de la maison. La case en rangée 2, colonne 5 est dans la chambre d'amis, la pièce de Béatrice, et Émilie n'était pas dans la même pièce que Béatrice. Quelle case reste-t-il dans la rangée 2 ?",answer:"Émilie se trouve en rangée 2, colonne 2. Elle devait être dans la rangée 2 (quelque part au-dessus d'un homme, donc pas dans la rangée 8) ; la colonne 1 revient à Guillaume, la 3 à Antoine, la 4 est occupée, la 5 est dans la pièce de Béatrice et les colonnes 6 à 8 sont hors de la maison."},{personId:"D",after:["B","E"],nudge:"Denise était dans la 4e rangée et dans une colonne plus à gauche que celle de Clément. Quelles colonnes sont encore libres dans cette rangée ?",reasoning:"Denise était dans la 4e rangée. Les colonnes 2 et 4 sont occupées par Émilie et Béatrice, la colonne 1 revient à Guillaume et la colonne 6 à Clément. En rangée 4, colonne 3 se trouve une étagère et en rangée 4, colonne 8 un coffre. La case en rangée 4, colonne 7 est exclue, car Denise était dans une colonne plus à gauche que celle de Clément, qui est dans la colonne 6. Que reste-t-il ?",answer:"Denise se trouve en rangée 4, colonne 5. Les colonnes 1, 2, 4 et 6 reviennent à d'autres, dans les colonnes 3 et 8 se trouvent une étagère et un coffre, et la colonne 7 n'est pas plus à gauche que celle de Clément."},{personId:"V",after:["B","E","D"],nudge:"Quelle rangée reste-t-il pour Virginie ? Regardez ensuite les colonnes 7 et 8, et Fanny.",reasoning:"Les rangées 1, 2 et 8 revenaient à Béatrice, Émilie et Virginie, comme on l'a vu avec Béatrice, donc Virginie va dans la rangée 8. Les colonnes 7 et 8 restent pour Fanny et Virginie, car Guillaume, Antoine et Clément ont chacun leur propre colonne. Dans la colonne 3, Antoine ne peut être que dans la rangée 5 ou 6 : en rangée 4, colonne 3 se trouve une étagère, la rangée 7 est hors de la maison, et Fanny devait être exactement une rangée plus bas, dans la moitié inférieure. Fanny était donc dans la rangée 6 ou 7, et dans ces rangées, la colonne 8 a des armoires. La colonne 7 revient donc à Fanny. Quelle case de la rangée 8 reste-t-il pour Virginie ?",answer:"Virginie se trouve en rangée 8, colonne 8. La rangée 8 lui revenait, les colonnes 1 à 4 sont hors de la maison, la colonne 5 est occupée par Denise, en rangée 8, colonne 6 se trouve une plante et la colonne 7 revient à Fanny."},{personId:"C",after:["B","E","D","V"],nudge:"Clément était dans la 6e colonne, dans une pièce sans aucune femme. Dans quelles pièces de la colonne 6 y a-t-il déjà une femme ?",reasoning:"Il n'y avait aucune femme dans la pièce de Clément. Dans la colonne 6, les rangées 1 et 2 sont hors de la maison, et en rangée 8, colonne 6 se trouve une plante. La case en rangée 3, colonne 6 est dans la chambre d'amis, où se trouve Béatrice. Les rangées 4 à 6 de la colonne 6 font partie du jardin d'hiver, où se trouve Denise. Quelle case reste-t-il ?",answer:"Clément se trouve en rangée 7, colonne 6. Les rangées 1 et 2 sont hors de la maison, dans la rangée 8 se trouve une plante, et il y a Béatrice dans la chambre d'amis et Denise dans le jardin d'hiver, deux femmes."},{personId:"F",after:["B","E","D","V","C"],nudge:"Fanny va dans la colonne 7, comme on l'a vu avec Virginie. Quelles rangées y sont encore libres dans la moitié inférieure ?",reasoning:"La colonne 7 revient à Fanny, comme on l'a vu avec Virginie. Les rangées 3, 5 et 6 sont encore libres ; Fanny se trouvait dans la moitié inférieure, donc dans la rangée 5 ou 6. Dans la rangée 5, Antoine serait une rangée plus haut, dans la rangée 4, mais c'est celle de Denise. Où va Fanny ?",answer:"Fanny se trouve en rangée 6, colonne 7. Dans la colonne 7, seules les rangées 3, 5 et 6 sont libres ; la rangée 3 n'est pas dans la moitié inférieure, et dans la rangée 5, Antoine devrait être dans la rangée 4, celle de Denise."},{personId:"A",after:["B","E","D","V","C","F"],nudge:"Fanny est maintenant sur la grille. Que dit sa carte à propos d'Antoine ?",reasoning:"Fanny était exactement une rangée en dessous d'Antoine, et Fanny se trouve dans la rangée 6. Selon sa propre carte, Antoine se trouvait dans la 3e colonne. Où arrivez-vous alors ?",answer:"Antoine se trouve en rangée 5, colonne 3. Il était dans la colonne 3 et exactement une rangée au-dessus de Fanny, qui se trouve dans la rangée 6."},{personId:"G",after:["B","E","D","V","C","F","A"],nudge:"Guillaume est le dernier à ne pas encore être sur la grille. Que dit sa carte ?",reasoning:"La rangée 3 et la colonne 1 sont les seules encore libres. Là, Guillaume est exactement deux colonnes à gauche d'Antoine et exactement deux rangées au-dessus de lui, comme le dit sa carte.",answer:"Guillaume se trouve en rangée 3, colonne 1. C'est la dernière rangée et la dernière colonne libres : exactement deux colonnes à gauche d'Antoine et exactement deux rangées au-dessus de lui."}],Ee="Virginie gît dans la cave à vin. Fanny était la seule suspecte dans la cave à vin ; Clément est dans la chambre, Denise dans le jardin d'hiver, Antoine dans la cuisine, et Béatrice, Émilie et Guillaume dans la chambre d'amis et le cabinet de travail. Fanny est donc la coupable.",_e={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},je={source:Qe,model:Fe,date:xe,steps:$e,murderer:Ee,review:_e},Ge="e82e6e33b7b4",Re="vertaler + keurder (claude-opus-5-5)",ke="2026-10-26",Se=[{personId:"A",after:[],nudge:"Commencez par Aurélie. Sa carte parle de la rangée du bas : quelles cases de cette rangée se trouvent dans la maison ?",reasoning:"Aurélie était dans la rangée du bas, la rangée 8. Dans la rangée 8, les cases des colonnes 1 à 4, 7 et 8 sont hors de la maison. En rangée 8, colonne 6, il y a une plante, et personne ne peut s'y trouver. Quelle case de la rangée 8 reste alors ?",answer:"Aurélie se trouve en rangée 8, colonne 5. Dans la rangée 8, les cases des colonnes 1 à 4, 7 et 8 sont hors de la maison et, en rangée 8, colonne 6, il y a une plante."},{personId:"V",after:["A"],nudge:"Aurélie est dans le boudoir, et sa carte dit qu'une autre femme s'y trouvait. Quelle femme cela peut-il être, et où ?",reasoning:"D'après la carte d'Aurélie, quelqu'un d'autre dans sa pièce était une femme. Dans le boudoir, la colonne 5 est occupée par Aurélie et, en rangée 8, colonne 6, il y a une plante ; seule la case en rangée 7, colonne 6 est encore libre. Les femmes sont Daphné, Élise et Vanina. Daphné n'était pas dans la même pièce qu'Aurélie, et Élise était dans la 2e colonne. Qui doit donc être dans cette case libre ?",answer:"Vanina se trouve en rangée 7, colonne 6. C'est la seule case libre du boudoir, et Daphné (pas dans la pièce d'Aurélie) et Élise (colonne 2) ne peuvent pas y être."},{personId:"G",after:["A","V"],nudge:"Regardez Gaston : il se trouvait devant une fenêtre. Passez les fenêtres en revue en gardant Charles, Élise et François à l'esprit.",reasoning:"Charles était exactement trois rangées au-dessus d'Aurélie, donc la rangée 5 est pour Charles ; la colonne 2 est pour Élise. Les cases devant une fenêtre sont en rangée 1, colonnes 1 et 2 ; en rangée 2, colonne 8 ; en rangée 5, colonne 8 ; en rangée 6, colonne 1 (une plante est en rangée 3, colonne 8 ; Aurélie occupe la case en rangée 8, colonne 5). Celles en rangée 1, colonne 2 (Élise) et en rangée 5, colonne 8 (Charles) sont exclues. François était dans une colonne plus à gauche que celle d'Aurélie, donc dans les colonnes 1 à 4, et Gaston était exactement une rangée au-dessus de lui. Si Gaston était en rangée 6, colonne 1, François serait en rangée 7, mais Vanina y gît. Si Gaston était en rangée 1, colonne 1, François serait en rangée 2 : il y a une plante en rangée 2, colonne 1, la colonne 2 est pour Élise, en rangée 2, colonne 3, il y a l'armoire, et la case en rangée 2, colonne 4 est à côté de cette armoire (François ne se trouvait pas à côté d'une armoire). Laquelle reste ?",answer:"Gaston se trouve en rangée 2, colonne 8. Sont exclues : rangée 1, colonne 1 (en rangée 2, aucune case pour François dans une colonne plus à gauche que celle d'Aurélie : plante, colonne d'Élise, armoire, à côté de l'armoire), rangée 6, colonne 1 (rangée 7 occupée par Vanina), rangée 1, colonne 2 (Élise) et rangée 5, colonne 8 (Charles)."},{personId:"C",after:["A","V","G"],nudge:"Charles était exactement trois rangées au-dessus d'Aurélie. Quelle rangée est-ce, et dans quelles colonnes y a-t-il une plante ?",reasoning:"Aurélie est en rangée 8, donc Charles doit être en rangée 5. Il y a une plante en rangée 2, colonne 1, une en rangée 8, colonne 6 et une en rangée 3, colonne 8. La colonne 6 est occupée par Vanina et la colonne 8 par Gaston. Quelle case de la rangée 5 reste alors ?",answer:"Charles se trouve en rangée 5, colonne 1. Il doit être en rangée 5 (exactement trois rangées au-dessus d'Aurélie) et, parmi les colonnes avec une plante, la 6 (Vanina) et la 8 (Gaston) sont déjà occupées."},{personId:"F",after:["A","V","G","C"],nudge:"Gaston était exactement une rangée au-dessus de François, et François dans une colonne plus à gauche que celle d'Aurélie. Quelles sont cette rangée et ces colonnes ?",reasoning:"Gaston est en rangée 2, donc François doit être en rangée 3. Une colonne plus à gauche que celle d'Aurélie, ce sont les colonnes 1 à 4. La colonne 1 est occupée par Charles, la colonne 2 est pour Élise, et en rangée 3, colonne 3, il y a un coffre. Quelle case reste alors ?",answer:"François se trouve en rangée 3, colonne 4. Il doit être en rangée 3 (Gaston étant exactement une rangée au-dessus de lui) et dans une colonne plus à gauche que celle d'Aurélie ; la colonne 1 (Charles), la colonne 2 (Élise) et la colonne 3 (coffre) sont exclues."},{personId:"E",after:["A","V","G","C","F"],nudge:"Élise était dans la 2e colonne, dans une pièce sans homme. Quelles rangées sont encore libres ?",reasoning:"Dans la colonne 2, les rangées 1, 4 et 6 sont encore libres. La case en rangée 4, colonne 2 est dans la chambre, où se trouve François (un homme). La case en rangée 6, colonne 2 est dans le couloir, où se trouve Charles (un homme). Quelle case reste alors ?",answer:"Élise se trouve en rangée 1, colonne 2. La rangée 4 est exclue (François dans la chambre), la rangée 6 aussi (Charles dans le couloir) ; dans la salle à manger, il n'y a aucun homme."},{personId:"B",after:["A","V","G","C","F","E"],nudge:"Bernard était le seul homme dans sa pièce. Voyez quelles rangées et quelles colonnes sont encore libres.",reasoning:"Il reste libres les rangées 4 et 6, et les colonnes 3 et 7. En rangée 4, colonne 7, il y a la table. La case en rangée 4, colonne 3 est dans la chambre avec François, et la case en rangée 6, colonne 3 dans le couloir avec Charles ; Bernard n'y serait pas le seul homme. Quelle case reste alors ?",answer:"Bernard se trouve en rangée 6, colonne 7. En rangée 4, colonne 7, il y a une table, et en rangée 4, colonne 3 (François) comme en rangée 6, colonne 3 (Charles), il n'aurait pas été le seul homme."},{personId:"D",after:["A","V","G","C","F","E","B"],nudge:"Daphné est la dernière personne qui n'est pas encore sur le plateau. Quelle rangée et quelle colonne sont encore libres ?",reasoning:"Chaque rangée et chaque colonne contient exactement une personne. La rangée 4 et la colonne 3 sont les dernières sans personne. La case où elles se croisent est dans la chambre, et non dans le boudoir d'Aurélie, ce qui est conforme à la carte de Daphné.",answer:"Daphné se trouve en rangée 4, colonne 3. La rangée 4 et la colonne 3 sont les dernières libres, et la case où elles se croisent est dans la chambre, pas dans la pièce d'Aurélie."}],Oe="Vanina gît dans le boudoir, et Aurélie y est la seule suspecte : Aurélie est la coupable. Charles est dans le couloir, François et Daphné dans la chambre, Élise dans la salle à manger, Gaston dans la bibliothèque et Bernard dans la cuisine.",Pe={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-26"},Te={source:Ge,model:Re,date:ke,steps:Se,murderer:Oe,review:Pe},Ue=Object.assign({"/.demo/puzzles/i18n/fr/L1-00037ru.json":r,"/.demo/puzzles/i18n/fr/L1-00037sm.json":p,"/.demo/puzzles/i18n/fr/L1-00037ss.json":A,"/.demo/puzzles/i18n/fr/L2-000255s.json":w,"/.demo/puzzles/i18n/fr/L2-000255v.json":E,"/.demo/puzzles/i18n/fr/L2-000256n.json":O,"/.demo/puzzles/i18n/fr/L3-0001qi0.json":H,"/.demo/puzzles/i18n/fr/L3-0002cvm.json":ne,"/.demo/puzzles/i18n/fr/L3-0002cvz.json":ce,"/.demo/puzzles/i18n/fr/L4-0002klf.json":ve,"/.demo/puzzles/i18n/fr/L4-0002klr.json":Be,"/.demo/puzzles/i18n/fr/L4-0002km3.json":ze,"/.demo/puzzles/i18n/fr/L5-0002sbj.json":je,"/.demo/puzzles/i18n/fr/L5-005oou4.json":Te});export{Ue as default};
